openShow=async function(id,seasonNo){const firstOpen=!dialog.open;if(firstOpen){dialog.querySelector('#dialogContent').innerHTML='<div class="dialog-loading"><span class="spinner"></span><strong>Cargando episodios…</strong><small>La primera apertura puede tardar unos segundos.</small></div>';dialog.showModal()}dialog.setAttribute('aria-busy','true');const originalShowModal=dialog.showModal;dialog.showModal=()=>{};try{await loadShowContent(id,seasonNo)}finally{dialog.showModal=originalShowModal;dialog.removeAttribute('aria-busy')}};
function csvRows(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++}else if(c==='"')quote=!quote;else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);if(rows.length<2)return[];const heads=rows.shift().map(x=>x.trim().toLowerCase());return rows.map(r=>Object.fromEntries(heads.map((h,i)=>[h,r[i]||''])))}
function collectRecords(value,out=[]){if(Array.isArray(value))value.forEach(x=>collectRecords(x,out));else if(value&&typeof value==='object'){out.push(value);Object.values(value).forEach(x=>{if(x&&typeof x==='object')collectRecords(x,out)})}return out}
function normaliseTvTime(objects){const found=new Map();for(const r of objects){const name=r.show_name||r.series_name||r.show_title||r.serie||r.show?.name||r.show?.title||r.series?.name||((r.type==='show'||r.type==='series')&&(r.name||r.title));if(!name||typeof name!=='string'||name.length>180)continue;const watchedFlag=r.watched??r.seen??r.is_watched??r.status;const hasEpisode=r.episode_number!=null||r.episode!=null||r.episode?.number!=null||r.season_number!=null;let item=found.get(name.toLowerCase())||{name:name.trim(),episodes:0,listed:true};if(hasEpisode&&(watchedFlag!==false&&watchedFlag!=='false'&&watchedFlag!=='unwatched'))item.episodes++;const explicit=Number(r.watched_episodes||r.seen_episodes||r.episodes_watched||0);item.episodes=Math.max(item.episodes,explicit);found.set(name.toLowerCase(),item)}return [...found.values()]}
