document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="stop-watching"],[data-action="resume-watching"]');if(!button)return;const id=Number(button.dataset.id)||0,show=SHOWS.find(item=>item.id===id);if(!show)return;const previous=state.showStatus[id]||'watching',stopping=button.dataset.action==='stop-watching';button.disabled=true;state.showStatus[id]=stopping?'dropped':'watching';reconcileShowStatus(show);save();try{await persistTrackRow(id);showToast(stopping?'Guardada en Ya no sigo':'Serie retomada');if(dialog.open)openShow(id)}catch(error){state.showStatus[id]=previous;reconcileShowStatus(show);save();button.disabled=false;showToast(error.message)}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="movie-watched"]');if(!button)return;const id=Number(button.dataset.id)||0,movie=SHOWS.find(item=>item.id===id);if(!movie||mediaType(movie)!=='movie')return;const previous={watching:state.watching[id],watched:[...(state.watchedEpisodes[id]||[])],status:state.showStatus[id],watchlist:[...state.watchlist],history:[...state.history]},seen=watchedCountForShow(movie)>0;button.disabled=true;if(seen){state.watchedEpisodes[id]=[];state.watching[id]=0;state.history=state.history.filter(item=>Number(item.showId)!==id)}else{state.watchedEpisodes[id]=['1-1'];state.watching[id]=1;addHistory(id,['1-1'])}reconcileShowStatus(movie);save();try{await persistEpisodeRow(id,1,1,!seen);await persistTrackRow(id);showToast(seen?'Película marcada como no vista':'Película marcada como vista');if(dialog.open)openShow(id)}catch(error){state.watching[id]=previous.watching;state.watchedEpisodes[id]=previous.watched;if(previous.status===undefined)delete state.showStatus[id];else state.showStatus[id]=previous.status;state.watchlist=previous.watchlist;state.history=previous.history;save();button.disabled=false;showToast(error.message)}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="delete-series"]');if(!button)return;const id=Number(button.dataset.id)||0,show=SHOWS.find(item=>item.id===id),movie=mediaType(show)==='movie';if(!show||!window.confirm(`¿Eliminar ${show.title}? Se borrarán ${movie?'su estado de vista':'todos sus capítulos vistos'} y su progreso.`))return;button.disabled=true;try{await persistDeleteShow(id);delete state.watching[id];delete state.watchedEpisodes[id];delete state.showStatus[id];delete state.ratings[id];state.watchlist=state.watchlist.filter(item=>Number(item)!==id);state.history=state.history.filter(item=>Number(item.showId)!==id);const index=SHOWS.findIndex(item=>item.id===id);if(index>=0)SHOWS.splice(index,1);save();dialog.close();render(currentView);showToast('Título eliminado')}catch(error){button.disabled=false;showToast(error.message)}});
document.addEventListener('change',e=>{const action=e.target.dataset.action,id=Number(e.target.dataset.id)||0;if(action==='show-status'){state.showStatus[id]=['watching','paused','completed','dropped'].includes(e.target.value)?e.target.value:'watching';if(!state.watching[id])state.watching[id]=0;save();persistTrackRow(id).catch(error=>showToast(error.message));showToast('Estado actualizado')}if(action==='rate-show'){const rating=Number(e.target.value);if(rating>=1&&rating<=10)state.ratings[id]=rating;else delete state.ratings[id];save();persistTrackRow(id).catch(error=>showToast(error.message));showToast(rating?'Valoración guardada':'Valoración eliminada')}});
document.addEventListener('change',event=>{if(['show-status','rate-show'].includes(event.target.dataset.action))setTimeout(refreshVisibleView,0)});
dialog.addEventListener('close',refreshVisibleView);
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='toggle-profile-edit'){const form=document.querySelector('#profileForm');if(form)form.hidden=!form.hidden}});
document.addEventListener('submit',async e=>{if(e.target.id!=='profileForm')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),name=String(data.name||'').trim(),email=String(data.email||'').trim().toLowerCase(),bio=String(data.bio||'').trim(),color=String(data.avatarColor||'');if(name.length<2||name.length>80){showToast('El nombre debe tener entre 2 y 80 caracteres');return}if(email&&!e.target.elements.email.checkValidity()){showToast('Introduce un correo válido');return}state.name=name;state.profile={bio:bio.slice(0,240),avatarColor:/^#[0-9a-f]{6}$/i.test(color)?color:'#ff2d74'};save();try{await persistProfile(email);currentUser={...currentUser,name,email};render('profile');showToast('Perfil guardado')}catch(error){showToast(error.message)}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(registration=>registration.update()).catch(()=>{});
function setAuthMode(mode,hasUsers=true){authMode=mode;const register=mode==='register',forgot=mode==='forgot',reset=mode==='reset-confirm',login=mode==='login',password=document.querySelector('[name=password]'),name=document.querySelector('[name=name]'),username=document.querySelector('[name=username]'),email=document.querySelector('[name=email]'),identifier=document.querySelector('[name=identifier]'),confirm=document.querySelector('[name=confirmPassword]'),secondary=document.querySelector('#authSecondary'),titles={login:['Iniciar sesión','Introduce tu usuario y contraseña para entrar.'],register:['Crear tu cuenta','Empieza a construir tu biblioteca personal.'],forgot:['Recuperar tu cuenta','Introduce tu usuario o correo y te enviaremos un enlace seguro.'],'reset-confirm':['Nueva contraseña','Elige una contraseña nueva para volver a entrar.']},copy=titles[mode]||titles.login;document.querySelector('#authTitle').textContent=copy[0];document.querySelector('#authHelp').textContent=copy[1];document.querySelector('.auth-tabs').hidden=forgot||reset;document.querySelector('#nameField').hidden=!register;document.querySelector('#usernameField').hidden=forgot||reset;document.querySelector('#emailField').hidden=!register;document.querySelector('#recoveryField').hidden=!forgot;document.querySelector('#passwordField').hidden=forgot;document.querySelector('#confirmField').hidden=!(register||reset);document.querySelector('#registerPrivacy').hidden=!register;document.querySelector('#passwordStrength').hidden=!(register||reset);document.querySelector('#authSubmit').textContent=register?'Crear mi cuenta':forgot?'Enviar enlace':reset?'Guardar nueva contraseña':'Entrar';secondary.hidden=register;secondary.textContent=forgot||reset?'Volver al inicio de sesión':'He olvidado mi contraseña';password.autocomplete=register||reset?'new-password':'current-password';name.required=register;username.required=login||register;email.required=register;identifier.required=forgot;password.required=!forgot;confirm.required=register||reset;if(!register){name.value='';email.value=''}if(!forgot)identifier.value='';if(!(register||reset))confirm.value='';document.querySelectorAll('[data-auth-mode]').forEach(button=>{const active=button.dataset.authMode===mode;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});const error=document.querySelector('#authError');error.textContent='';error.classList.remove('success');if(!hasUsers&&login)document.querySelector('#authHelp').textContent='Todavía no hay cuentas. Selecciona “Crear cuenta” para comenzar.'}
document.querySelectorAll('[data-auth-mode]').forEach(button=>button.addEventListener('click',()=>setAuthMode(button.dataset.authMode)));
document.querySelector('#authSecondary').addEventListener('click',()=>{if(authMode==='login'){if(!passwordResetAvailable){const error=document.querySelector('#authError');error.textContent='La recuperación por correo todavía no está configurada.';error.classList.remove('success');return}setAuthMode('forgot')}else setAuthMode('login')});
document.querySelector('[data-action="toggle-password"]').addEventListener('click',e=>{const input=document.querySelector('[name=password]'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'Ocultar':'Ver';e.currentTarget.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña')});
document.querySelector('[name=password]').addEventListener('input',e=>{const value=e.target.value,score=[value.length>=8,value.length>=12,/[a-z]/.test(value)&&/[A-Z]/.test(value),/\d/.test(value),/[^\w]/.test(value)].filter(Boolean).length,bar=document.querySelector('#passwordStrength i'),label=document.querySelector('#passwordStrength small'),levels=['Usa 8 caracteres o más','Contraseña débil','Contraseña aceptable','Contraseña buena','Contraseña fuerte','Contraseña muy fuerte'];bar.style.width=`${score*20}%`;bar.style.background=score<2?'#ff6b6b':score<4?'#ffb74d':'#35d69f';label.textContent=levels[score]});
authForm.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(authForm)),error=document.querySelector('#authError'),button=document.querySelector('#authSubmit');error.textContent='';error.classList.remove('success');if(!authForm.checkValidity()){authForm.reportValidity();return}if((authMode==='register'||authMode==='reset-confirm')&&b.password!==b.confirmPassword){error.textContent='Las contraseñas no coinciden';document.querySelector('[name=confirmPassword]').focus();return}delete b.confirmPassword;button.disabled=true;const original=button.textContent;button.innerHTML='<span class="spinner"></span> Comprobando…';try{if(authMode==='forgot'){const r=await apiFetch('./api.php?action=password_reset_request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identifier:b.identifier})}),data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo enviar la solicitud');error.textContent=data.message;error.classList.add('success');return}if(authMode==='reset-confirm'){const r=await apiFetch('./api.php?action=password_reset_confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:resetToken,password:b.password})}),data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo cambiar la contraseña');csrfToken=data.csrfToken||csrfToken;resetToken='';history.replaceState({},'',location.pathname);authForm.reset();setAuthMode('login');document.querySelector('#authHelp').textContent=data.message;return}const r=await apiFetch(`./api.php?action=${authMode}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo acceder');currentUser=data.user;csrfToken=data.csrfToken||csrfToken;if(authMode==='register'){state={...structuredClone(defaultState),name:data.user.name};await apiFetch('./api.php?action=data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(serverSnapshot())})}authScreen.hidden=true;authForm.reset();await loadUserData()}catch(err){error.textContent=err.message}finally{button.disabled=false;button.textContent=original}});
async function loadUserData(){try{const response=await fetch('./api.php?action=data',{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudieron cargar los datos');const local=readLocalBackup(),recoverLocal=data.exists&&activityScore(data.state)===0&&activityScore(local?.state)>0;if(recoverLocal){state=ensureState(local.state);tmdbToken=data.tmdbToken||'';SHOWS=[];if(Array.isArray(local.catalog))storeShows(local.catalog);await persistServer();showToast('Datos recuperados y migrados a SQLite')}else if(data.exists&&data.state){state=ensureState(data.state);tmdbToken=data.tmdbToken||'';SHOWS=[];if(Array.isArray(data.catalog))storeShows(data.catalog);writeLocalBackup(Date.parse(data.savedAt)||Date.now())}else{state=ensureState({...structuredClone(defaultState),name:currentUser.name});writeLocalBackup();await persistServer()}render();refreshTrackedStatuses().catch(()=>{})}catch(error){const local=readLocalBackup();if(local?.state){state=ensureState(local.state);SHOWS=[];if(Array.isArray(local.catalog))storeShows(local.catalog);render();showToast('Sin conexión: usando copia de emergencia')}else throw error}}
async function bootstrap(){try{localStorage.removeItem('maraton-state');localStorage.removeItem('maraton-tmdb-token');localStorage.removeItem('maraton-catalog');const r=await fetch('./api.php?action=status',{cache:'no-store'}),status=await r.json();csrfToken=status.csrfToken||'';passwordResetAvailable=status.passwordResetAvailable===true;document.querySelector('[data-auth-mode="register"]').hidden=status.registrationOpen===false;if(/^[a-f0-9]{64}$/.test(resetToken)){setAuthMode('reset-confirm',status.hasUsers);authScreen.hidden=false;return}if(!status.authenticated){setAuthMode(status.hasUsers?'login':'register',status.hasUsers);authScreen.hidden=false;return}currentUser=status.user;authScreen.hidden=true;await loadUserData()}catch{authScreen.hidden=false;document.querySelector('#authError').textContent='No se pudo conectar con el servidor.'}}
